<?php if ($files): ?><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Fichier</th><th>Commande</th><th>Statut</th><th>Date</th></tr></thead><tbody><?php foreach ($files as $f): ?><tr><td><a href="/fichier/<?= (int) $f['id'] ?>"><?= e($f['orig_name']) ?></a> <small class="muted"><?= Files::human((int) $f['size']) ?></small></td><td><?= $f['ref'] ? '<a href="/commande/' . e($f['ref']) . '">' . e($f['ref']) . '</a>' : '—' ?></td><td><?= status_badge(Files::STATUS, $f['status']) ?></td><td><?= fdate($f['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="panel center"><p class="muted">Aucun fichier envoyé.</p></div><?php endif; ?>
